/**
 * Forma comparable de un texto: sin tildes, en minuscula y con los espacios
 * normalizados.
 *
 * Hasta DEC-FRONT-14 esta funcion quitaba ademas la secuencia "nd", para que
 * quien escribiera "Tamarindo" encontrase el "Tamario" que publicaba el IGN.
 * Ese apano dejo de hacer falta al reparar los nombres y se retiro: hacia
 * coincidir cadenas que eran distintas y, sobre todo, escondia el defecto de
 * los datos en vez de resolverlo.
 */
export function normalizar(texto) {
    return String(texto ?? '')
        .normalize('NFD')
        .replace(/[̀-ͯ]/g, '')
        .toLowerCase()
        .split(/\s+/)
        .join(' ')
        .trim();
}

/** Todas las localidades de un distrito, por su codigo DTA. */
export function pobladosDe(codigoDistrito) {
    return POBLADOS[codigoDistrito] ?? [];
}

/**
 * Localidades de un distrito que casan con lo tecleado.
 *
 * Las que empiezan por la consulta van primero: quien escribe "san" espera
 * "San Antonio" antes que "Barrio San Luis". Con la consulta vacia devuelve el
 * principio de la lista, para que el campo sugiera algo nada mas enfocarlo.
 */
export function buscarPoblados(codigoDistrito, consulta = '', { limite = 25 } = {}) {
    const lista = pobladosDe(codigoDistrito);
    const aguja = normalizar(consulta);
    if (aguja === '') return lista.slice(0, limite);

    const empiezan = [];
    const contienen = [];
    for (const nombre of lista) {
        const heno = normalizar(nombre);
        if (heno.startsWith(aguja)) empiezan.push(nombre);
        else if (heno.includes(aguja)) contienen.push(nombre);
        if (empiezan.length >= limite) break;
    }
    return [...empiezan, ...contienen].slice(0, limite);
}
